// UsageProviderDisplayName resolves a provider_key to its public display name
// per usage-stats.md §2.4/§4.3. Never returns an empty string: unknown
// preset ids and unrecognized keys fall back to the key text itself.
func UsageProviderDisplayName(providerKey string) string {
	switch providerKey {
	case "builtin":
		return "内置"
	case "cli":
		return "CLI"
	case "custom":
		return "自定义"
	}
	const presetPrefix = "preset:"
	if len(providerKey) > len(presetPrefix) && providerKey[:len(presetPrefix)] == presetPrefix {
		id := providerKey[len(presetPrefix):]
		if name, ok := usagePresetCatalog[id]; ok {
			return name
		}
		return id
	}
	return providerKey
}
